clc;
close all;
clear all;

% Define output folder
output_folder = '/home/uqhkarim/Normative_HCTSA/Scripts/LittDataset/FeatureExtraction/';
% Use the file generated by the previous Atlasing script
% input_data_filename = fullfile(output_folder, 'DS4100_ZScores_Power_Coherence.mat');
% input_data_filename = fullfile(output_folder, 'DS4100_ZScores_Power_Coherence_per_part.mat');

input_data_filename = fullfile(output_folder, 'Data_AllContacts_BothDatasets_epochs_PowCoh_per_part.mat');

if exist(input_data_filename, 'file')
    fprintf('Loading pre-processed Power/Coh data from %s...\n', input_data_filename);
    % Load DS4100 abnormality scores, raw atlas features, and ROI mappings
    load(input_data_filename, ...
         'DS4100_Power',...
         'DS4100_Coherence_Mean',...
         'X_frauscher', ...
         'DS4100_ROIs', ...
         'Frauscher_ROIs', ...
         'DS4100_ann', ...
         'band_names');
    fprintf('Data loaded successfully.\n');
else
    error('File not found. Please run the ROI Mapping/Z-scoring script first.');
end
DS4100_both_features=[DS4100_Power, DS4100_Coherence_Mean]; % Raw features (11380 x 10)
%% 1. Global Normalization to [0, 1] range based on Frauscher bounds
fprintf('\n--- Normalizing features to the [0, 1] range using Frauscher min/max ---\n');

num_features = size(X_frauscher, 2);
frauscher_min_vals = min(X_frauscher, [], 1, 'omitnan');
frauscher_max_vals = max(X_frauscher, [], 1, 'omitnan');
frauscher_range = frauscher_max_vals - frauscher_min_vals;

% Normalize Frauscher features
X_frauscher_norm = NaN(size(X_frauscher));
for f = 1:num_features
    if frauscher_range(f) == 0
        X_frauscher_norm(:, f) = 0;
    else
        X_frauscher_norm(:, f) = (X_frauscher(:, f) - frauscher_min_vals(f)) / frauscher_range(f);
    end
end

%% 2. Normalize DS4100 Data Per-Patient
fprintf('--- Normalizing DS4100 features per-patient ---\n');

patient_ids = {DS4100_ann.all_clinical_info_epoch.participant_id}';
unique_patients = unique(patient_ids);
DS4100_normalized_01 = NaN(size(DS4100_both_features));

% Note: We apply normalization to the raw-scale features (the Z-scoring logic 
% is reapplied afterwards to ensure the [0,1] scale is preserved)
for p_id = 1:length(unique_patients)
    pid = unique_patients{p_id};
    p_idx = find(strcmp(patient_ids, pid));
    
    for f = 1:num_features
        if frauscher_range(f) == 0
            DS4100_normalized_01(p_idx, f) = 0;
        else
            % Map DS4100 contact values to the [0,1] Frauscher scale
            DS4100_normalized_01(p_idx, f) = (DS4100_both_features(p_idx, f) - frauscher_min_vals(f)) / frauscher_range(f);
        end
    end
end

%% 3. Recalculate ROI-based Absolute Z-scores on Normalized Data
fprintf('\n--- Recalculating Absolute Z-scores on Normalized Scale ---\n');
num_ds_contacts = size(DS4100_normalized_01, 1);
DS4100_Final_Z = NaN(num_ds_contacts, num_features);

for i = 1:num_ds_contacts
    current_roi = DS4100_ROIs{i};
    if strcmp(current_roi, 'No ROI'), continue; end
    
    roi_idx = find(strcmp(Frauscher_ROIs, current_roi));
    if isempty(roi_idx), continue; end
    
    % Use normalized atlas data for distribution
    normative_data = X_frauscher_norm(roi_idx, :);
    mu = mean(normative_data, 1, 'omitnan');
    sigma = std(normative_data, 0, 1, 'omitnan');
    
    for f = 1:num_features
        if sigma(f) > 0
            z = (DS4100_normalized_01(i, f) - mu(f)) / sigma(f);
            DS4100_Final_Z(i, f) = (z);
        else
            DS4100_Final_Z(i, f) = 0;
        end
    end
end

%% 4. Save Results
feature_names = [cellfun(@(x) ['Power_', x], band_names, 'UniformOutput', false), ...
                 cellfun(@(x) ['Coherence_', x], band_names, 'UniformOutput', false)];

% output_zscore_filename = fullfile(output_folder, 'DS4100_Power_Coh_Normalized_Final.mat');
output_zscore_filename = fullfile(output_folder, 'DS4100_Power_Coh_Normalized_Final_per_part.mat');

fprintf('Saving final normalized Z-scores to %s...\n', output_zscore_filename);

save(output_zscore_filename, ...
     'DS4100_Final_Z', ... % This is X_all for your classification script
     'DS4100_ann', ...
     'feature_names', ...
     'DS4100_ROIs', ...
     'X_frauscher_norm', ...
     '-v7.3');

fprintf('Processing complete.\n');